private boolean canAttackMovePos() {
        LivingEntity target = this.crossBowman.getTarget();
        BlockPos pos = crossBowman.getMovePos();

        if (target != null && pos != null && crossBowman.getShouldMovePos()) {
            boolean targetIsFar = target.distanceTo(this.crossBowman) >= 32D;
            boolean posIsClose = pos.distSqr(this.crossBowman.getOnPos()) <= 15.0D;
            boolean posIsFar = pos.distSqr(this.crossBowman.getOnPos()) > 15.0D;

            if (posIsFar) {
                return false;
            }

            else if (posIsClose && targetIsFar){
                return false;
            }
        }
        return true;
    }

private void handleFollow(@NotNull LivingEntity owner, boolean inRange, boolean isFar){
        boolean ownerClose = owner.distanceToSqr(this.crossBowman) <= 100;

        if (ownerClose) {
            if (inRange) this.crossBowman.getNavigation().stop();
            if (isFar) this.crossBowman.getNavigation().moveTo(target, this.speedModifier);
        }
    }

private void handleHoldPos(@NotNull Vec3 pos, boolean inRange){
        boolean posClose = pos.distanceToSqr(this.crossBowman.position()) <= 50;

        if (posClose) {
            if (inRange) this.crossBowman.getNavigation().stop();
        }
    }

private void handleWander(boolean inRange, boolean isFar, boolean isClose){
        if (inRange) this.crossBowman.getNavigation().stop();
        if (isFar) this.crossBowman.getNavigation().moveTo(crossBowman, this.speedModifier);
    }

public boolean canUse() {
        LivingEntity livingentity = this.recruit.getTarget();
        if (livingentity != null && livingentity.isAlive()) {
            if(this.recruit.getShouldRanged() && IRangedRecruit.isTooDeepUnderwater(livingentity)){
                this.recruit.setTarget(null);
                return false;
            }
            if(!isHoldingBow(this.recruit)){
                recruit.switchMainHandItem(RecruitRangedBowAttackGoal::isBow);

                return false;
            }

            this.target = livingentity;
            float distance = this.target.distanceTo(this.recruit);

            boolean canTackMovePos = canAttackMovePos();
            boolean shouldRanged = this.recruit.getShouldRanged();
            boolean canAttack = this.recruit.canAttack(target);
            boolean notPassive = this.recruit.getState() != 3;
            boolean notNeedsToGetFood = !this.recruit.needsToGetFood();
            boolean canSee = this.recruit.getSensing().hasLineOfSight(target);
            // Option 2: only engage targets that are actually visible. Without line of sight
            // the target is dropped so the recruit does not chase enemies behind walls.
            // (LoS in the area search is disabled; this goal-level check is the single source
            // of truth for "may I act on this target".)
            if(!canSee){
                recruit.setTarget(null);
                return false;
            }
            return distance >= stopRange && canTackMovePos && notNeedsToGetFood && canAttack && notPassive && shouldRanged;
        } else {
            return false;
        }
    }

