        }

        int k = EnchantmentHelper.getItemEnchantmentLevel(Enchantments.MULTISHOT, shooter.getMainHandItem());
        if (k > 0) {
            //TODO:
        }

        this.shootArrow(shooter, projectileEntity, x, y, z);

